type SearchDiscussionPostsRow struct {
	ID            int64   `json:"id"`
	Title         string  `json:"title"`
	Body          string  `json:"body"`
	UserID        int64   `json:"user_id"`
	Pinned        int64   `json:"pinned"`
	Type          string  `json:"type"`
	EventDate     *string `json:"event_date"`
	Location      *string `json:"location"`
	ImageUrl      *string `json:"image_url"`
	CreatedAt     string  `json:"created_at"`
	UpdatedAt     string  `json:"updated_at"`
	DeletedAt     *string `json:"deleted_at"`
	UserName      string  `json:"user_name"`
	UserAvatarUrl string  `json:"user_avatar_url"`
	CommentCount  int64   `json:"comment_count"`
	Votes         int64   `json:"votes"`
	UserVote      int64   `json:"user_vote"`
}

func (q *Queries) SearchDiscussionPosts(ctx context.Context, arg SearchDiscussionPostsParams) ([]SearchDiscussionPostsRow, error) {
	rows, err := q.db.QueryContext(ctx, searchDiscussionPosts, arg.CurrentUserID, arg.Query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SearchDiscussionPostsRow
	for rows.Next() {
		var i SearchDiscussionPostsRow
		if err := rows.Scan(
			&i.ID,
			&i.Title,
			&i.Body,
			&i.UserID,
			&i.Pinned,
			&i.Type,
			&i.EventDate,
			&i.Location,
			&i.ImageUrl,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.DeletedAt,
			&i.UserName,
			&i.UserAvatarUrl,
			&i.CommentCount,
			&i.Votes,
			&i.UserVote,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

