const upsertDiscussionCommentVote = `-- name: UpsertDiscussionCommentVote :one
INSERT INTO discussion_comment_votes (
    comment_id, user_id, vote
) VALUES (
    ?1, ?2, ?3
)
ON CONFLICT (comment_id, user_id) DO UPDATE SET
    vote = excluded.vote
RETURNING comment_id, user_id, vote
`

type UpsertDiscussionCommentVoteParams struct {
	CommentID int64 `json:"comment_id"`
	UserID    int64 `json:"user_id"`
	Vote      int64 `json:"vote"`
}

func (q *Queries) UpsertDiscussionCommentVote(ctx context.Context, arg UpsertDiscussionCommentVoteParams) (DiscussionCommentVote, error) {
	row := q.db.QueryRowContext(ctx, upsertDiscussionCommentVote, arg.CommentID, arg.UserID, arg.Vote)
	var i DiscussionCommentVote
	err := row.Scan(&i.CommentID, &i.UserID, &i.Vote)
	return i, err
}

